 if(direct!=null)return direct;
 const m={newLife:pickNum(w,['newLifeInsurance','新生命保険料'])??0,oldLife:pickNum(w,['oldLifeInsurance','旧生命保険料'])??0,medical:pickNum(w,['nursingMedicalInsurance','介護医療保険料'])??0,newPension:pickNum(w,['newPersonalPensionInsurance','新個人年金保険料'])??0,oldPension:pickNum(w,['oldPersonalPensionInsurance','旧個人年金保険料'])??0,under23Dependent:false};
